      "खेतों में पकी फसल और घर में आया नया धान,",
      "मकर संक्रांति पर झुककर करते हैं धरती मां का ध्यान।",
      "अन्नदाता किसान के चेहरे पर खिली है लाली,",
      "संक्रांति ने भर दी सबकी खुशियों की थाली!"
